private const char *
get_default_magic(void)
{
        static const char hmagic[] = "/.magic/magic.mgc";
        static char *default_magic;
        char *home, *hmagicpath;

#ifndef WIN32
        struct stat st;

        if (default_magic) {
                free(default_magic);
                default_magic = NULL;
        }
        if ((home = getenv("HOME")) == NULL)
                return MAGIC;

        if (asprintf(&hmagicpath, "%s/.magic.mgc", home) < 0)
                return MAGIC;
        if (stat(hmagicpath, &st) == -1) {
                free(hmagicpath);
                if (asprintf(&hmagicpath, "%s/.magic", home) < 0)
                        return MAGIC;
                if (stat(hmagicpath, &st) == -1)
                        goto out;
                if (S_ISDIR(st.st_mode)) {
                        free(hmagicpath);
                        if (asprintf(&hmagicpath, "%s/%s", home, hmagic) < 0)
                                return MAGIC;
                        if (access(hmagicpath, R_OK) == -1)
                                goto out;
                }
        }

        if (asprintf(&default_magic, "%s:%s", hmagicpath, MAGIC) < 0)
                goto out;
        free(hmagicpath);
        return default_magic;
out:
        default_magic = NULL;
        free(hmagicpath);
        return MAGIC;
#else
        hmagicpath = NULL;

        if (default_magic) {
                free(default_magic);
                default_magic = NULL;
        }

        /* First, try to get a magic file from user-application data */
        if ((home = getenv("LOCALAPPDATA")) != NULL)
                _w32_append_path(&hmagicpath, "%s%s", home, hmagic);

        /* Second, try to get a magic file from the user profile data */
        if ((home = getenv("USERPROFILE")) != NULL)
                _w32_append_path(&hmagicpath,
                    "%s/Local Settings/Application Data%s", home, hmagic);

        /* Third, try to get a magic file from Common Files */
        if ((home = getenv("COMMONPROGRAMFILES")) != NULL)
                _w32_append_path(&hmagicpath, "%s%s", home, hmagic);

        /* Fourth, try to get magic file relative to exe location */
        _w32_get_magic_relative_to(&hmagicpath, NULL);

        /* Fifth, try to get magic file relative to dll location */
        _w32_get_magic_relative_to(&hmagicpath, _w32_dll_instance);

        /* Avoid MAGIC constant - it likely points to a file within MSys tree */
        default_magic = hmagicpath;
        return default_magic;
#endif
}

public const char *
magic_getpath(const char *magicfile, int action)
{
        if (magicfile != NULL)
                return magicfile;

        magicfile = getenv("MAGIC");
        if (magicfile != NULL)
                return magicfile;

        return action == FILE_LOAD ? get_default_magic() : MAGIC;
}

